window.AssemblyCall=(()=>{
 let frame=null,watch=null,busy=false,context=null,sdk=null,generation=0;
 const panel=document.createElement('section');panel.className='call-panel';panel.hidden=true;panel.setAttribute('popover','manual');panel.setAttribute('aria-label','Classroom video call');
 panel.innerHTML='<header><strong id="callTitle">Classroom call</strong><button type="button" data-call="minimize" aria-expanded="true">Minimize</button><button type="button" data-call="leave">Leave call</button></header><p role="status"></p><div id="callFrame"></div>';document.body.append(panel);
 const status=t=>panel.querySelector('[role="status"]').textContent=t;
 function load(){return sdk??=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://unpkg.com/@daily-co/daily-js@0.94.0/dist/daily.js';script.crossOrigin='anonymous';script.onload=resolve;script.onerror=()=>{sdk=null;script.remove();reject(Error('Video controls could not load. Check your connection.'));};document.head.append(script);});}
 function show(){panel.hidden=false;if(!panel.matches(':popover-open'))panel.showPopover();panel.classList.remove('minimized');document.body.classList.toggle('meeting-active',Boolean(frame));const button=panel.querySelector('[data-call="minimize"]');button.textContent='Minimize';button.setAttribute('aria-expanded','true');}
 async function leave(note=''){generation++;busy=false;clearInterval(watch);watch=null;const old=frame;frame=null;context=null;document.body.classList.remove('meeting-active');panel.hidden=!note;if(!note&&panel.matches(':popover-open'))panel.hidePopover();if(note)show();status(note);if(old)await old.destroy();}
 async function join(classId,roomId=null){if(context?.classId===classId&&context?.roomId===roomId&&frame){show();return;}if(busy)return;const cleanup=leave();const ticket=++generation;busy=true;try{await cleanup;if(ticket!==generation)return;AssemblyMedia.close();panel.hidden=false;panel.showPopover();panel.classList.remove('minimized');document.body.classList.add('meeting-active');panel.querySelector('[data-call="minimize"]').textContent='Minimize';panel.querySelector('[data-call="minimize"]').setAttribute('aria-expanded','true');status('Connecting securely…');const client=AssemblyAccount.connection();const {data,error}=await client.functions.invoke('classroom-call',{body:{class_id:classId,room_id:roomId}});if(ticket!==generation)return;if(error){let message='Call connection unavailable. Confirm classroom-call is deployed in Supabase.';try{message=(await error.context.json()).error||message;}catch{}throw Error(message);}if(data.error)throw Error(data.error);await load();if(ticket!==generation)return;context={classId,roomId:['prebrief','debrief'].includes(data.stage)?null:roomId,stage:data.stage};panel.querySelector('#callTitle').textContent=data.label||'Classroom call';frame=window.Daily.createFrame(panel.querySelector('#callFrame'),{iframeStyle:{width:'100%',height:'100%',border:'0'},showLeaveButton:true});const currentFrame=frame;frame.on('left-meeting',()=>{if(frame===currentFrame)leave();});frame.on('error',()=>{if(frame===currentFrame)status('Call interrupted. Leave and rejoin to try again.');});await frame.join({url:data.url,token:data.token});if(ticket!==generation)return;status('Live meeting: enable camera or microphone below. Share screen presents a window or tab. Minimize keeps your call connected.');watch=setInterval(async()=>{if(!context)return;const current=context;try{const {data:s,error:e}=await client.rpc('assembly_session_snapshot',{target_class:classId});if(context!==current)return;if(e){await leave('Classroom access could not be verified. Rejoin to try again.');return;}if(s.stage!==current.stage){if(['preparation','finished'].includes(s.stage)){await leave('The session has ended.');return;}const wasLobby=['prebrief','debrief'].includes(current.stage),isLobby=['prebrief','debrief'].includes(s.stage);if(wasLobby===isLobby){context.stage=s.stage;return;}if(isLobby){await join(classId);return;}if(!s.teacher&&s.rooms.length===1){await join(classId,s.rooms[0].id);return;}await leave('Negotiation has started. Open a classroom and select Join classroom meeting to visit its participants.');}}catch{if(context===current)await leave('Connection lost. Rejoin to verify classroom access.');}},5000);}catch(e){if(ticket===generation)await leave(e.message);}finally{if(ticket===generation)busy=false;}}
 panel.addEventListener('click',e=>{const action=e.target.closest('[data-call]')?.dataset.call;if(action==='leave')leave();if(action==='minimize'){const collapsed=panel.classList.toggle('minimized');document.body.classList.toggle('meeting-active',!collapsed&&Boolean(frame));e.target.textContent=collapsed?'Expand':'Minimize';e.target.setAttribute('aria-expanded',String(!collapsed));}});
 window.addEventListener('pagehide',()=>{clearInterval(watch);frame?.destroy();});return {join,leave,show,active:()=>Boolean(frame)||busy};
})();
